a=json.load(open(r/'canyon-extraction.json'));d=json.load(open(r/'delivery-verification.json'));MB=lambda n:f'{n/1e6:.2f}'.replace('.',',');shots=['canyon-before-40s.png','canyon-enriched-12s.png','canyon-enriched-40s.png','canyon-enriched-120s.png','preview-canyon-start.png']
